insert into public.words (level, term, meaning_ko, example_en, example_ko, pos, category, subcategory) values
('E','expression','식','An algebraic expression contains variables, numbers, and operation symbols.','대수식은 변수, 숫자, 연산 기호를 포함합니다.','noun','math_en','algebra'),
('E','term','항','In the expression 3x + 7, ''3x'' and ''7'' are terms.','식 3x + 7에서 ''3x''와 ''7''은 항입니다.','noun','math_en','algebra'),
('E','constant','상수','In the expression 2y - 3, -3 is the constant term.','식 2y - 3에서 -3은 상수항입니다.','noun','math_en','algebra'),
('E','base','밑','In x², the base is x.','x²에서 밑은 x입니다.','noun','math_en','algebra'),
('E','difference','차','The difference between 10 and 4 is 6.','10과 4의 차는 6입니다.','noun','math_en','algebra'),
('E','quotient','몫','The quotient of 20 divided by 5 is 4.','20을 5로 나눈 몫은 4입니다.','noun','math_en','algebra'),
('E','inequality','부등식','An inequality uses symbols like <, >, ≤, or ≥.','부등식은 <, >, ≤, 또는 ≥와 같은 기호를 사용합니다.','noun','math_en','algebra'),
('E','domain','정의역','The domain of a function is the set of all possible inputs.','함수의 정의역은 가능한 모든 입력의 집합입니다.','noun','math_en','algebra'),
('E','range','치역','The range of a function is the set of all possible outputs.','함수의 치역은 가능한 모든 출력의 집합입니다.','noun','math_en','algebra'),
('E','solution','해','The solution to 3x = 9 is x = 3.','3x = 9의 해는 x = 3입니다.','noun','math_en','algebra'),
('E','intercept','절편','The y-intercept is where the line crosses the y-axis.','y절편은 직선이 y축과 교차하는 지점입니다.','noun','math_en','algebra'),
('E','linear','선형의','A linear equation graphs as a straight line.','선형 방정식은 직선으로 그래프가 그려집니다.','adjective','math_en','algebra'),
('E','quadratic','이차의','A quadratic equation has a term with x².','이차 방정식은 x² 항을 가지고 있습니다.','adjective','math_en','algebra'),
('E','cubic','삼차의','A cubic polynomial has a term with x³.','삼차 다항식은 x³ 항을 가지고 있습니다.','adjective','math_en','algebra'),
('E','term by term','항별로','We multiply the polynomials term by term.','우리는 다항식을 항별로 곱합니다.','adverb phras','math_en','algebra'),
('E','solve','풀다','Solve the equation for x.','x에 대해 방정식을 푸세요.','verb','math_en','algebra'),
('E','evaluate','값을 계산하다','Evaluate the expression when x = 3.','x = 3일 때 식의 값을 계산하세요.','verb','math_en','algebra'),
('E','identity','항등식','An identity is an equation that is true for all values of the variable.','항등식은 변수의 모든 값에 대해 참인 방정식입니다.','noun','math_en','algebra'),
('E','set builder notation','집합 건축 표기법','Set builder notation is used to describe sets.','집합 건축 표기법은 집합을 설명하는 데 사용됩니다.','noun phrase','math_en','algebra'),
('E','interval notation','구간 표기법','Interval notation uses brackets and parentheses to represent sets of numbers.','구간 표기법은 숫자 집합을 나타내기 위해 대괄호와 소괄호를 사용합니다.','noun phrase','math_en','algebra'),
('E','limit','극한','The limit of the function f(x) as x approaches 2 is 5.','x가 2에 가까워질 때 함수 f(x)의 극한값은 5입니다.','noun','math_en','calculus'),
('E','rate of change','변화율','The rate of change of distance with respect to time is velocity.','시간에 대한 거리의 변화율은 속도입니다.','noun phrase','math_en','calculus'),
('E','tangent','접선','The tangent line touches the curve at a single point.','접선은 곡선에 한 점에서 접합니다.','noun','math_en','calculus'),
('E','continuous','연속적인','A function is continuous if its graph can be drawn without lifting the pen.','함수는 펜을 떼지 않고 그래프를 그릴 수 있다면 연속입니다.','adjective','math_en','calculus'),
('E','infinity','무한대','The sequence approaches infinity.','그 수열은 무한대로 수렴합니다.','noun','math_en','calculus'),
('E','sequence','수열','An arithmetic sequence has a common difference.','등차수열은 공차가 같습니다.','noun','math_en','calculus'),
('E','series','급수','The sum of an infinite geometric series can be finite.','무한 등비급수의 합은 유한할 수 있습니다.','noun','math_en','calculus'),
('E','asymptote','점근선','The graph approaches the asymptote but never touches it.','그래프는 점근선에 가까워지지만 절대 만나지 않습니다.','noun','math_en','calculus'),
('E','reciprocal','역수','The reciprocal of 2 is 1/2.','2의 역수는 1/2입니다.','noun','math_en','calculus'),
('E','magnitude','크기','The magnitude of the vector is calculated using the Pythagorean theorem.','벡터의 크기는 피타고라스 정리를 사용하여 계산됩니다.','noun','math_en','calculus'),
('E','vector','벡터','A vector has both magnitude and direction.','벡터는 크기와 방향을 모두 가집니다.','noun','math_en','calculus'),
('E','scalar','스칼라','A scalar quantity has only magnitude.','스칼라 양은 크기만 가집니다.','noun','math_en','calculus'),
('E','exponential','지수의','Exponential growth is very rapid.','지수적 성장은 매우 빠릅니다.','adjective','math_en','calculus'),
('E','logarithm','로그','The logarithm of 100 to base 10 is 2.','밑이 10인 100의 로그는 2입니다.','noun','math_en','calculus'),
('E','summation','합계','The summation symbol is sigma (Σ).','합계 기호는 시그마(Σ)입니다.','noun','math_en','calculus'),
('E','average rate of change','평균 변화율','The average rate of change between two points on a curve is the slope of the secant line.','곡선 위의 두 점 사이의 평균 변화율은 할선의 기울기입니다.','noun phrase','math_en','calculus'),
('E','instantaneous rate of change','순간 변화율','The instantaneous rate of change is the derivative of the function.','순간 변화율은 함수의 도함수입니다.','noun phrase','math_en','calculus'),
('E','triangle','삼각형','An equilateral triangle has three equal sides.','정삼각형은 세 변의 길이가 같습니다.','noun','math_en','geometry'),
('E','circle','원','The circumference of a circle is pi times its diameter.','원의 둘레는 파이 곱하기 지름입니다.','noun','math_en','geometry'),
('E','polygon','다각형','A pentagon is a polygon with five sides.','오각형은 변이 다섯 개인 다각형입니다.','noun','math_en','geometry'),
('E','perimeter','둘레','The perimeter of the garden is 50 meters.','정원의 둘레는 50미터입니다.','noun','math_en','geometry'),
('E','radius','반지름','The radius is half the diameter of a circle.','반지름은 원 지름의 절반입니다.','noun','math_en','geometry'),
('E','diameter','지름','The diameter passes through the center of the circle.','지름은 원의 중심을 통과합니다.','noun','math_en','geometry'),
('E','congruent','합동인','These two triangles are congruent.','이 두 삼각형은 합동입니다.','adjective','math_en','geometry'),
('E','similar','닮은','Similar triangles have the same shape but different sizes.','닮은 삼각형은 모양은 같지만 크기는 다릅니다.','adjective','math_en','geometry'),
('E','vertex','꼭짓점','A triangle has three vertices.','삼각형은 세 개의 꼭짓점을 가집니다.','noun','math_en','geometry'),
('E','edge','모서리','A cube has 12 edges.','정육면체는 12개의 모서리를 가지고 있습니다.','noun','math_en','geometry'),
('E','face','면','A die has six faces.','주사위는 여섯 개의 면을 가지고 있습니다.','noun','math_en','geometry'),
('E','height','높이','The height of the pyramid is measured from the apex to the center of the base.','피라미드의 높이는 꼭대기에서 밑면의 중심까지 측정됩니다.','noun','math_en','geometry'),
('E','acute angle','예각','An acute angle is less than 90 degrees.','예각은 90도보다 작습니다.','noun phrase','math_en','geometry'),
('E','obtuse angle','둔각','An obtuse angle is greater than 90 degrees but less than 180 degrees.','둔각은 90도보다 크고 180도보다 작습니다.','noun phrase','math_en','geometry'),
('E','right angle','직각','The corner of a book is a right angle.','책의 모퉁이는 직각입니다.','noun phrase','math_en','geometry'),
('E','straight angle','평각','A straight angle measures 180 degrees.','평각은 180도를 측정합니다.','noun phrase','math_en','geometry'),
('E','reflex angle','반사각','A reflex angle is greater than 180 degrees.','반사각은 180도보다 큽니다.','noun phrase','math_en','geometry'),
('E','isosceles triangle','이등변삼각형','An isosceles triangle has two equal sides and two equal angles.','이등변삼각형은 두 변과 두 각이 같습니다.','noun phrase','math_en','geometry'),
('E','scalene triangle','부등변삼각형','A scalene triangle has no equal sides or angles.','부등변삼각형은 같은 변이나 각이 없습니다.','noun phrase','math_en','geometry'),
('E','quadrilateral','사각형','A square is a special type of quadrilateral.','정사각형은 특별한 종류의 사각형입니다.','noun','math_en','geometry'),
('E','rhombus','마름모','A rhombus has four equal sides.','마름모는 네 변의 길이가 같습니다.','noun','math_en','geometry'),
('E','trapezoid','사다리꼴','A trapezoid has at least one pair of parallel sides.','사다리꼴은 적어도 한 쌍의 평행한 변을 가집니다.','noun','math_en','geometry'),
('E','cone','원뿔','The volume of a cone is one-third the area of the base times the height.','원뿔의 부피는 밑면 넓이 곱하기 높이의 3분의 1입니다.','noun','math_en','geometry'),
('E','cylinder','원기둥','The volume of a cylinder is the area of the base times the height.','원기둥의 부피는 밑면 넓이 곱하기 높이입니다.','noun','math_en','geometry'),
('E','sphere','구','A sphere is a perfectly round geometrical object in three-dimensional space.','구는 3차원 공간에서 완벽하게 둥근 기하학적 객체입니다.','noun','math_en','geometry'),
('E','Probability','확률','The probability of rolling a 6 on a fair die is 1/6.','공정한 주사위를 굴려 6이 나올 확률은 1/6입니다.','noun','math_en','stats'),
('E','Mean','평균','The mean score on the test was 85.','시험 점수의 평균은 85점이었습니다.','noun','math_en','stats'),
('E','Median','중앙값','The median age of the participants was 25.','참가자들의 중앙 연령은 25세였습니다.','noun','math_en','stats'),
('E','Mode','최빈값','The mode of the dataset is the number that appears most frequently.','데이터셋의 최빈값은 가장 자주 나타나는 숫자입니다.','noun','math_en','stats'),
('E','Range','범위','The range of the data is the difference between the highest and lowest values.','데이터의 범위는 가장 높은 값과 가장 낮은 값의 차이입니다.','noun','math_en','stats'),
('E','Standard Deviation','표준 편차','A low standard deviation indicates that the data points are close to the mean.','낮은 표준 편차는 데이터 포인트가 평균에 가깝다는 것을 나타냅니다.','noun phrase','math_en','stats'),
('E','Distribution','분포','The histogram shows the distribution of student heights.','히스토그램은 학생들의 키 분포를 보여줍니다.','noun','math_en','stats'),
('E','Sample','표본','We took a random sample of 100 voters.','우리는 100명의 유권자를 무작위로 표본 추출했습니다.','noun','math_en','stats'),
('E','Outcome','결과','Each flip of the coin has two possible outcomes: heads or tails.','각 동전 던지기에는 앞면 또는 뒷면의 두 가지 가능한 결과가 있습니다.','noun','math_en','stats'),
('E','Event','사건','Drawing a red card is an event in a deck of cards.','빨간 카드를 뽑는 것은 카드 덱에서의 한 사건입니다.','noun','math_en','stats'),
('E','Percent','퍼센트, 백분율','Fifty percent of the students passed the exam.','학생들의 50퍼센트가 시험에 합격했습니다.','noun','math_en','stats'),
('E','Average','평균','The average rainfall this month was higher than usual.','이번 달 평균 강우량은 평소보다 많았습니다.','noun','math_en','stats'),
('E','Correlation','상관 관계','There is a strong positive correlation between study time and grades.','공부 시간과 성적 사이에는 강한 양의 상관 관계가 있습니다.','noun','math_en','stats'),
('E','Outlier','이상치','The outlier in the data set significantly skewed the average.','데이터 세트의 이상치가 평균을 상당히 왜곡했습니다.','noun','math_en','stats'),
('E','Bar Chart','막대 그래프','The bar chart shows the sales figures for each month.','막대 그래프는 각 월의 판매 수치를 보여줍니다.','noun phrase','math_en','stats'),
('E','Pie Chart','원 그래프','The pie chart illustrates the budget allocation.','원 그래프는 예산 할당을 보여줍니다.','noun phrase','math_en','stats'),
('E','Histogram','히스토그램','A histogram is used to display the frequency distribution of continuous data.','히스토그램은 연속 데이터의 빈도 분포를 표시하는 데 사용됩니다.','noun','math_en','stats'),
('E','Population','모집단','The study surveyed the entire population of high school students in the city.','그 연구는 도시의 고등학생 전체 모집단을 조사했습니다.','noun','math_en','stats'),
('E','Parameter','모수','The mean and standard deviation are parameters of a normal distribution.','평균과 표준 편차는 정규 분포의 모수입니다.','noun','math_en','stats'),
('E','Statistic','통계치','The sample mean is a statistic used to estimate the population mean.','표본 평균은 모집단 평균을 추정하는 데 사용되는 통계치입니다.','noun','math_en','stats'),
('E','Variance','분산','Variance measures how spread out the data is from the mean.','분산은 데이터가 평균에서 얼마나 퍼져 있는지를 측정합니다.','noun','math_en','stats'),
('E','Random','무작위의','A random selection ensures that each item has an equal chance of being chosen.','무작위 선택은 각 항목이 선택될 동등한 기회를 갖도록 보장합니다.','adjective','math_en','stats'),
('E','Inference','추론','Statistical inference allows us to draw conclusions about a population from a sample.','통계적 추론은 표본으로부터 모집단에 대한 결론을 도출할 수 있게 합니다.','noun','math_en','stats'),
('E','Regression','회귀','Regression analysis helps predict one variable based on another.','회귀 분석은 다른 변수에 기초하여 한 변수를 예측하는 데 도움이 됩니다.','noun','math_en','stats'),
('E','equation','방정식','Solve the equation x + 5 = 10.','방정식 x + 5 = 10을 푸시오.','noun','math_en',NULL),
('E','variable','변수','In the equation, x is the variable.','방정식에서 x는 변수입니다.','noun','math_en',NULL),
('E','fraction','분수','1/2 is a simple fraction.','1/2은 간단한 분수입니다.','noun','math_en',NULL),
('E','numerator','분자','The numerator is the top part of a fraction.','분자는 분수의 윗부분입니다.','noun','math_en',NULL),
('E','denominator','분모','The denominator is the bottom part of a fraction.','분모는 분수의 아랫부분입니다.','noun','math_en',NULL),
('E','exponent','지수','In x^2, 2 is the exponent.','x^2에서 2는 지수입니다.','noun','math_en',NULL),
('E','coefficient','계수','The coefficient of 3x is 3.','3x의 계수는 3입니다.','noun','math_en',NULL),
('E','polynomial','다항식','x^2 + 2x + 1 is a polynomial.','x^2 + 2x + 1은 다항식입니다.','noun','math_en',NULL),
('E','factor','인수, 약수','2 and 3 are factors of 6.','2와 3은 6의 인수입니다.','noun','math_en',NULL),
('E','slope','기울기','The slope of the line is 2.','직선의 기울기는 2입니다.','noun','math_en',NULL),
('E','ratio','비율','The ratio of boys to girls is 1:2.','남학생 대 여학생의 비율은 1:2입니다.','noun','math_en',NULL),
('E','probability','확률','The probability of rolling a 6 is 1/6.','6을 굴릴 확률은 1/6입니다.','noun','math_en',NULL),
('E','geometry','기하학','Geometry studies shapes and space.','기하학은 도형과 공간을 연구합니다.','noun','math_en',NULL),
('E','theorem','정리 (수학)','The Pythagorean theorem relates the sides of a right triangle.','피타고라스 정리는 직각삼각형의 변의 길이를 관련시킵니다.','noun','math_en',NULL),
('E','hypotenuse','빗변','The hypotenuse is the longest side of a right triangle.','빗변은 직각삼각형에서 가장 긴 변입니다.','noun','math_en',NULL),
('E','angle','각','The angle in the corner is 90 degrees.','모서리의 각은 90도입니다.','noun','math_en',NULL),
('E','derivative','미분','The derivative measures the rate of change.','미분은 변화율을 측정합니다.','noun','math_en',NULL),
('E','integral','적분','Integral calculus deals with areas under curves.','적분학은 곡선 아래의 넓이를 다룹니다.','noun','math_en',NULL),
('E','sum','합','The sum of 2 and 3 is 5.','2와 3의 합은 5입니다.','noun','math_en',NULL),
('E','product','곱','The product of 4 and 5 is 20.','4와 5의 곱은 20입니다.','noun','math_en',NULL),
('E','average','평균','The average score was 85.','평균 점수는 85점이었습니다.','noun','math_en',NULL),
('E','median','중앙값','The median is the middle value in a sorted list.','중앙값은 정렬된 목록에서 가운데 값입니다.','noun','math_en',NULL),
('E','mode','최빈값','The mode is the most frequent value.','최빈값은 가장 자주 나타나는 값입니다.','noun','math_en',NULL),
('E','root','근 (방정식)','The root of x - 3 = 0 is 3.','x - 3 = 0의 근은 3입니다.','noun','math_en',NULL),
('E','square root','제곱근','The square root of 9 is 3.','9의 제곱근은 3입니다.','noun phrase','math_en',NULL),
('E','cube root','세제곱근','The cube root of 8 is 2.','8의 세제곱근은 2입니다.','noun phrase','math_en',NULL),
('E','percentage','백분율','50% is half of the total.','50%는 전체의 절반입니다.','noun','math_en',NULL),
('E','decimal','소수','0.5 is the decimal for 1/2.','0.5는 1/2의 소수입니다.','noun','math_en',NULL),
('E','integer','정수','Integers include positive and negative whole numbers.','정수에는 양수와 음수 정수가 포함됩니다.','noun','math_en',NULL),
('E','coordinate','좌표','The coordinate (2, 3) is in the first quadrant.','좌표 (2, 3)은 제1사분면에 있습니다.','noun','math_en',NULL),
